import * as THREE from 'three';
// One emitter per depth band; layers differ by count, length and speed only - never by sprite size.
const LAYERS = [
  { tag: 'precip-near', count: 200,  near: 0,  far: 5,  len: 0.8,  opacity: 0.5,  speed: 14 },
  { tag: 'precip-mid',  count: 600,  near: 5,  far: 25, len: 0.4,  opacity: 0.3,  speed: 11 },
  { tag: 'precip-far',  count: 1500, near: 25, far: 60, len: 0.15, opacity: 0.15, speed: 8 }
];
export function makePrecip(kind = 'rain', rng = Math.random) {
  const group = new THREE.Group(); group.userData.tag = 'precip';
  for (const L of LAYERS) {
    const snow = kind === 'snow', n = snow ? Math.round(L.count * 0.45) : L.count;   // snow: ~1000 flakes total, fixed
    const verts = snow ? 1 : 2, pos = new Float32Array(n * 3 * verts);
    for (let i = 0; i < n; i++) {
      const a = rng() * Math.PI * 2, d = L.near + rng() * (L.far - L.near);
      const x = Math.cos(a) * d, z = Math.sin(a) * d, y = rng() * 30;
      if (snow) pos.set([x, y, z], i * 3); else pos.set([x, y, z, x, y - L.len, z], i * 6);   // streak >= 6:1 along the fall axis
    }
    const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const obj = snow
      ? new THREE.Points(geo, new THREE.PointsMaterial({ color: 0xe8eef5, size: 0.035, sizeAttenuation: true, transparent: true, opacity: L.opacity, depthWrite: false })) // <= 0.05 world units
      : new THREE.LineSegments(geo, new THREE.LineBasicMaterial({ color: 0xcfd8e3, transparent: true, opacity: L.opacity, depthWrite: false }));
    obj.userData = { tag: L.tag, speed: snow ? L.speed * 0.12 : L.speed, stride: verts * 3 };
    obj.frustumCulled = false; group.add(obj);
  }
  return group;
}
export function tickPrecip(group, camera, dt) {
  group.position.set(camera.position.x, 0, camera.position.z);      // the bands travel with the camera
  for (const obj of group.children) {
    const p = obj.geometry.attributes.position, fall = obj.userData.speed * dt, stride = obj.userData.stride;
    for (let i = 1; i < p.array.length; i += stride) {
      p.array[i] -= fall; if (stride === 6) p.array[i + 3] -= fall;
      if (p.array[i] < 0) { p.array[i] += 30; if (stride === 6) p.array[i + 3] += 30; }
    }
    p.needsUpdate = true;
  }
}
